 10	import java.util.List;
 11	import javax.sql.DataSource;
 12	
 13	public class Main {
 14	    public static void main(String[] args) {
 15	        DataSource ds = Database.connect(required("DB_URL"), required("DB_USER"), required("DB_PASSWORD"));
 16	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 17	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 18	        boolean archiveCopy = !"false".equalsIgnoreCase(System.getenv("HOTEL_ARCHIVE_COPY"));
 19	
 20	        MessageLog log = new PostgresMessageLog(ds);
 21	        ReservationRepository reservations = new ReservationRepository(ds);
 22	        ReservationService service = new ReservationService(reservations,
 23	                messageSender(log, testMode, archiveCopy));
 24	        new Routes(service, reservations, log).start(port);
 25	    }
 26	
 27	    /**
 28	     * Único lugar que decide as regras de mensagens desta instalação, da mais externa para a mais interna.
 29	     * Uma regra nova (horário, limite por hóspede...) entra aqui, com o escopo em que vale.
 30	     */
 31	    static MessageSender messageSender(MessageLog log, boolean testMode, boolean archiveCopy) {
 32	        List<MessageRule> rules = new java.util.ArrayList<>();
 33	        rules.add(new MessageRule(RuleScope.ALWAYS, next -> new BlockInvalidAddress(next, log)));
 34	        if (archiveCopy) {
 35	            rules.add(new MessageRule(RuleScope.OUTSIDE_TEST_MODE_ONLY, ArchiveCopy::new));
 36	        }
 37	        rules.add(new MessageRule(RuleScope.TEST_MODE_ONLY, RedirectToTest::new));
 38	        return MessagePipeline.build(testMode, new LogSender(log), rules);
 39	    }
 40	
 41	    private static String required(String name) {
 42	        String value = System.getenv(name);
 43	        if (value == null || value.isBlank()) throw new IllegalStateException("Variável de ambiente ausente: " + name);
 44	        return value;
 45	    }
 46	}
 47	package br.com.marealta.web;
 48	
 49	import br.com.marealta.domain.*;
 50	import br.com.marealta.messaging.MessageLog;
 51	import br.com.marealta.persistence.ReservationRepository;
 52	import br.com.marealta.report.OccupancyReport;
 53	import br.com.marealta.report.RevenueReport;
 54	import br.com.marealta.service.ReservationService;
 55	import com.fasterxml.jackson.core.JsonProcessingException;
 56	import com.fasterxml.jackson.databind.JsonNode;
 57	import com.fasterxml.jackson.databind.ObjectMapper;
 58	import com.fasterxml.jackson.databind.SerializationFeature;
 59	import com.fasterxml.jackson.databind.json.JsonMapper;
 60	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 61	import io.javalin.Javalin;
 62	import io.javalin.http.Context;
 63	
 64	import java.time.LocalDate;
 65	import java.time.YearMonth;
 66	import java.time.format.DateTimeParseException;
 67	import java.util.LinkedHashMap;
 68	import java.util.Map;
 69	
 70	public class Routes {
 71	    private final ObjectMapper mapper = JsonMapper.builder()
 72	            .addModule(new JavaTimeModule())
 73	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 74	            .enable(com.fasterxml.jackson.core.JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
 75	            .build();
 76	    private final ReservationService service;
 77	    private final ReservationRepository reservations;
 78	    private final MessageLog messages;
 79	
 80	    public Routes(ReservationService service, ReservationRepository reservations, MessageLog messages) {
 81	        this.service = service;
 82	        this.reservations = reservations;
 83	        this.messages = messages;
 84	    }
 85	
 86	    public Javalin start(int port) {
 87	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 88	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
 89	        app.exception(Exception.class, (e, ctx) -> {
 90	            e.printStackTrace();
 91	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 92	        });
 93	        app.error(404, ctx -> {
 94	            if (ctx.result() == null) error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
 95	        });
 96	
 97	        app.get("/rooms", ctx -> json(ctx, 200, RoomCatalog.all().stream().map(this::roomView).toList()));
 98	        app.post("/reservations", ctx -> json(ctx, 201, view(service.create(parseNewReservation(ctx)))));
 99	        app.get("/reservations/{id}", ctx -> json(ctx, 200, view(service.get(id(ctx)))));
100	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, view(service.confirm(id(ctx)))));
101	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, view(service.cancel(id(ctx)))));
102	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, view(service.checkIn(id(ctx)))));
103	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, service.checkOut(id(ctx))));
104	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, service.document(id(ctx))));
105	        app.get("/messages", ctx -> json(ctx, 200, messages.all().stream().map(m -> {
106	            Map<String, Object> v = new LinkedHashMap<>();
107	            v.put("id", m.id());
108	            v.put("channel", m.channel());
109	            v.put("to", m.to());
110	            v.put("subject", m.subject());
111	            v.put("body", m.body());
112	            v.put("status", m.status());
113	            return v;
114	        }).toList()));
115	        app.get("/reports/occupancy", ctx -> csv(ctx,
116	                new OccupancyReport(reservations, parseDate(ctx.queryParam("date"), "date")).render()));
117	        app.get("/reports/revenue", ctx -> csv(ctx,
118	                new RevenueReport(reservations, parseMonth(ctx.queryParam("month"))).render()));
119	        return app.start(port);
120	    }
121	
122	    private Map<String, Object> roomView(Room r) {
123	        Map<String, Object> v = new LinkedHashMap<>();
124	        v.put("number", r.number());
125	        v.put("type", r.type());
126	        v.put("capacity", r.capacity());
127	        v.put("nightlyRate", r.nightlyRate());
128	        return v;
129	    }
130	
131	    private Map<String, Object> view(Reservation r) {
132	        Map<String, Object> v = new LinkedHashMap<>();
133	        v.put("id", r.id());
134	        v.put("roomNumber", r.roomNumber());
135	        v.put("guestName", r.guestName());
136	        v.put("guestEmail", r.guestEmail());
137	        v.put("guestCpf", r.guestCpf());
138	        v.put("checkIn", r.checkInDate());
139	        v.put("checkOut", r.checkOutDate());
140	        v.put("guests", r.guests());
141	        v.put("ratePlan", r.ratePlan());
142	        v.put("nights", r.nights());
143	        v.put("subtotal", r.subtotal());
144	        v.put("discount", r.discount());
145	        v.put("total", r.total());
146	        v.put("status", r.status());
147	        v.put("amountPaid", r.amountPaid());
148	        v.put("refund", r.refund());
149	        return v;
150	    }
151	
152	    private ReservationService.NewReservation parseNewReservation(Context ctx) {
153	        JsonNode body;
154	        try {
155	            body = mapper.readTree(ctx.body());
156	        } catch (JsonProcessingException e) {
157	            throw ApiException.invalidRequest("O corpo não é um JSON válido");
158	        }
159	        if (body == null || !body.isObject()) throw ApiException.invalidRequest("O corpo deve ser um objeto JSON");
160	
161	        int roomNumber = integer(body, "roomNumber");
162	        String name = text(body, "guestName");
163	        String email = text(body, "guestEmail");
164	        String cpf = text(body, "guestCpf");
165	        LocalDate checkIn = parseDate(text(body, "checkIn"), "checkIn");
166	        LocalDate checkOut = parseDate(text(body, "checkOut"), "checkOut");
167	        int guests = integer(body, "guests");
168	        RatePlan plan;
169	        try {
170	            plan = RatePlan.valueOf(text(body, "ratePlan"));
171	        } catch (IllegalArgumentException e) {
172	            throw ApiException.invalidRequest("ratePlan inválido");
173	        }
174	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalidRequest("A saída deve ser depois da entrada");
175	        if (guests < 1) throw ApiException.invalidRequest("É preciso pelo menos um hóspede");
176	        return new ReservationService.NewReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
177	    }
178	
179	    private static String text(JsonNode body, String field) {
180	        JsonNode n = body.get(field);
181	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
182	            throw ApiException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
183	        }
184	        return n.asText();
185	    }
186	
187	    private static int integer(JsonNode body, String field) {
188	        JsonNode n = body.get(field);
189	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
190	            throw ApiException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
191	        }
192	        return n.asInt();
193	    }
194	
195	    private static LocalDate parseDate(String value, String field) {
196	        try {
197	            if (value == null) throw new DateTimeParseException("ausente", "", 0);
198	            return LocalDate.parse(value);
199	        } catch (DateTimeParseException e) {
200	            throw ApiException.invalidRequest("Data inválida em " + field + " (use AAAA-MM-DD)");
201	        }
202	    }
203	
204	    private static YearMonth parseMonth(String value) {
205	        try {
206	            if (value == null) throw new DateTimeParseException("ausente", "", 0);
207	            return YearMonth.parse(value);
208	        } catch (DateTimeParseException e) {
209	            throw ApiException.invalidRequest("Mês inválido (use AAAA-MM)");
210	        }
211	    }
212	
213	    private static long id(Context ctx) {
214	        try {
215	            return Long.parseLong(ctx.pathParam("id"));
216	        } catch (NumberFormatException e) {
217	            throw ApiException.reservationNotFound(0);
218	        }
219	    }
220	
221	    private void json(Context ctx, int status, Object body) throws JsonProcessingException {
222	        ctx.status(status).contentType("application/json; charset=utf-8").result(mapper.writeValueAsString(body));
223	    }
224	
225	    private void csv(Context ctx, String body) {
226	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
227	    }
228	
229	    private void error(Context ctx, int status, String code, String message) {
230	        try {
231	            json(ctx, status, Map.of("error", code, "message", message));
232	        } catch (JsonProcessingException e) {
233	            ctx.status(status);
234	        }
235	    }
236	}
237	package br.com.marealta.service;
238	
239	import br.com.marealta.domain.*;
240	import br.com.marealta.messaging.Message;
241	import br.com.marealta.messaging.MessageSender;
242	import br.com.marealta.persistence.ReservationRepository;
243	
244	import java.time.LocalDate;
245	
246	public class ReservationService {
247	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
248	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
249	
250	    private final ReservationRepository reservations;
251	    private final MessageSender sender;
252	
253	    public ReservationService(ReservationRepository reservations, MessageSender sender) {
254	        this.reservations = reservations;
255	        this.sender = sender;
256	    }
257	
258	    public Reservation create(NewReservation req) {
259	        Room room = RoomCatalog.find(req.roomNumber()).orElseThrow(() -> ApiException.roomNotFound(req.roomNumber()));
260	        if (req.guests() > room.capacity()) throw ApiException.capacityExceeded(room.capacity());
261	        Pricing.Quote quote = Pricing.quote(room, req.checkIn(), req.checkOut(), req.ratePlan());
262	        return reservations.insert(new Reservation(0, room.number(), req.guestName(), req.guestEmail(),
263	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote,
264	                ReservationStatus.PENDING, Money.ZERO, null));
265	    }
266	
267	    public Reservation get(long id) {
268	        return reservations.find(id).orElseThrow(() -> ApiException.reservationNotFound(id));
269	    }
270	
271	    public Reservation confirm(long id) {
272	        Reservation r = reservations.modify(id, Reservation::confirm);
273	        sender.send(Message.email(r.guestEmail(), "Reserva confirmada - Pousada Maré Alta", confirmationBody(r)));
274	        return r;
275	    }
276	
277	    public Reservation cancel(long id) {
278	        return reservations.modify(id, Reservation::cancel);
279	    }
280	
281	    public Reservation checkIn(long id) {
282	        return reservations.modify(id, Reservation::checkIn);
283	    }
284	
285	    public Receipt checkOut(long id) {
286	        return receiptOf(reservations.modify(id, Reservation::checkOut));
287	    }
288	
289	    public Receipt document(long id) {
290	        Reservation r = get(id);
291	        r.requirePaid();
292	        return receiptOf(r);
293	    }
294	
295	    private Receipt receiptOf(Reservation r) {
296	        return Receipt.of(r, RoomCatalog.find(r.roomNumber()).orElseThrow());
297	    }
298	
299	    private String confirmationBody(Reservation r) {
300	        return "Olá, " + r.guestName() + "!\n\n"
301	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
302	                + receiptOf(r).text() + "\n\n"
303	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
304	                + "Até breve!";
305	    }
306	}

