213	    private static long id(Context ctx) {
214	        try {
215	            return Long.parseLong(ctx.pathParam("id"));
216	        } catch (NumberFormatException e) {
217	            throw ApiException.reservationNotFound(0);
218	        }
219	    }
220	
221	    private void json(Context ctx, int status, Object body) throws JsonProcessingException {
222	        ctx.status(status).contentType("application/json; charset=utf-8").result(mapper.writeValueAsString(body));
223	    }
224	
225	    private void csv(Context ctx, String body) {
226	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
227	    }
228	
229	    private void error(Context ctx, int status, String code, String message) {
230	        try {
231	            json(ctx, status, Map.of("error", code, "message", message));
232	        } catch (JsonProcessingException e) {
233	            ctx.status(status);
234	        }
235	    }
