246	public class ReservationService {
247	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
248	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
249	
250	    private final ReservationRepository reservations;
251	    private final MessageSender sender;
252	
253	    public ReservationService(ReservationRepository reservations, MessageSender sender) {
254	        this.reservations = reservations;
255	        this.sender = sender;
256	    }
257	
258	    public Reservation create(NewReservation req) {
259	        Room room = RoomCatalog.find(req.roomNumber()).orElseThrow(() -> ApiException.roomNotFound(req.roomNumber()));
260	        if (req.guests() > room.capacity()) throw ApiException.capacityExceeded(room.capacity());
261	        Pricing.Quote quote = Pricing.quote(room, req.checkIn(), req.checkOut(), req.ratePlan());
262	        return reservations.insert(new Reservation(0, room.number(), req.guestName(), req.guestEmail(),
263	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote,
264	                ReservationStatus.PENDING, Money.ZERO, null));
265	    }
266	
267	    public Reservation get(long id) {
268	        return reservations.find(id).orElseThrow(() -> ApiException.reservationNotFound(id));
269	    }
270	
271	    public Reservation confirm(long id) {
272	        Reservation r = reservations.modify(id, Reservation::confirm);
273	        sender.send(Message.email(r.guestEmail(), "Reserva confirmada - Pousada Maré Alta", confirmationBody(r)));
274	        return r;
275	    }
276	
277	    public Reservation cancel(long id) {
278	        return reservations.modify(id, Reservation::cancel);
279	    }
280	
281	    public Reservation checkIn(long id) {
282	        return reservations.modify(id, Reservation::checkIn);
283	    }
284	
285	    public Receipt checkOut(long id) {
286	        return receiptOf(reservations.modify(id, Reservation::checkOut));
287	    }
288	
289	    public Receipt document(long id) {
290	        Reservation r = get(id);
291	        r.requirePaid();
292	        return receiptOf(r);
293	    }
294	
295	    private Receipt receiptOf(Reservation r) {
296	        return Receipt.of(r, RoomCatalog.find(r.roomNumber()).orElseThrow());
297	    }
298	
299	    private String confirmationBody(Reservation r) {
300	        return "Olá, " + r.guestName() + "!\n\n"
301	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
302	                + receiptOf(r).text() + "\n\n"
303	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
304	                + "Até breve!";
305	    }
