     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {}
    11	
    12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    13	
    14	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    15	        BigDecimal subtotal = Money.ZERO;
    16	        int nights = 0;
    17	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    18	            subtotal = subtotal.add(nightPrice(room, night));
    19	            nights++;
    20	        }
    21	        BigDecimal discount = plan.discount(subtotal);
    22	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    23	    }
    24	
    25	    static BigDecimal nightPrice(Room room, LocalDate night) {
    26	        BigDecimal rate = room.nightlyRate();
    27	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    28	    }
    29	
    30	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    31	    static boolean isHighSeason(LocalDate date) {
    32	        Month month = date.getMonth();
    33	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    34	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    35	    }
    36	}
