 10	import java.util.function.Consumer;
 11	import javax.sql.DataSource;
 12	
 13	public class ReservationRepository {
 14	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
 15	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
 16	
 17	    private final DataSource ds;
 18	
 19	    public ReservationRepository(DataSource ds) { this.ds = ds; }
 20	
 21	    /** Grava a reserva se o quarto estiver livre em todas as noites; a trava impede duas reservas simultâneas. */
 22	    public Reservation insert(Reservation draft) {
 23	        try (Connection c = ds.getConnection()) {
 24	            c.setAutoCommit(false);
 25	            try {
 26	                try (PreparedStatement lock = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
 27	                    lock.setLong(1, draft.roomNumber());
 28	                    lock.execute();
 29	                }
 30	                try (PreparedStatement ps = c.prepareStatement("""
 31	                        SELECT 1 FROM reservations
 32	                        WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?""")) {
 33	                    ps.setInt(1, draft.roomNumber());
 34	                    ps.setDate(2, Date.valueOf(draft.checkOutDate()));
 35	                    ps.setDate(3, Date.valueOf(draft.checkInDate()));
 36	                    try (ResultSet rs = ps.executeQuery()) {
 37	                        if (rs.next()) throw ApiException.roomUnavailable();
 38	                    }
 39	                }
 40	                long id;
 41	                try (PreparedStatement ps = c.prepareStatement("""
 42	                        INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
 43	                            guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
 44	                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id""")) {
 45	                    bind(ps, draft);
 46	                    try (ResultSet rs = ps.executeQuery()) {
 47	                        rs.next();
 48	                        id = rs.getLong(1);
 49	                    }
 50	                }
 51	                c.commit();
 52	                return find(id).orElseThrow();
 53	            } catch (Exception e) {
 54	                c.rollback();
 55	                throw e;
 56	            }
 57	        } catch (SQLException e) {
 58	            throw new IllegalStateException(e);
 59	        }
 60	    }
 61	
 62	    public Optional<Reservation> find(long id) {
 63	        try (Connection c = ds.getConnection();
 64	             PreparedStatement ps = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
 65	            ps.setLong(1, id);
 66	            try (ResultSet rs = ps.executeQuery()) {
 67	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
 68	            }
 69	        } catch (SQLException e) {
 70	            throw new IllegalStateException(e);
 71	        }
 72	    }
 73	
 74	    /** Aplica uma mudança à reserva travada, numa transação, e devolve o resultado. */
 75	    public Reservation modify(long id, Consumer<Reservation> change) {
 76	        try (Connection c = ds.getConnection()) {
 77	            c.setAutoCommit(false);
 78	            try {
 79	                Reservation r;
 80	                try (PreparedStatement ps = c.prepareStatement(
 81	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ? FOR UPDATE")) {
 82	                    ps.setLong(1, id);
 83	                    try (ResultSet rs = ps.executeQuery()) {
 84	                        if (!rs.next()) throw ApiException.reservationNotFound(id);
 85	                        r = map(rs);
 86	                    }
 87	                }
 88	                change.accept(r);
 89	                try (PreparedStatement ps = c.prepareStatement(
 90	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
 91	                    ps.setString(1, r.status().name());
 92	                    ps.setBigDecimal(2, r.amountPaid());
 93	                    ps.setBigDecimal(3, r.refund());
 94	                    ps.setLong(4, id);
 95	                    ps.executeUpdate();
 96	                }
 97	                c.commit();
 98	                return r;
 99	            } catch (Exception e) {
100	                c.rollback();
101	                throw e;
102	            }
103	        } catch (SQLException e) {
104	            throw new IllegalStateException(e);
105	        }
106	    }
107	
108	    /** Reservas pagas que ocupam um quarto na noite dada. */
109	    public List<Reservation> paidOnNight(LocalDate night) {
110	        return query("WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND check_in <= ? AND check_out > ? "
111	                + "ORDER BY room_number, id", Date.valueOf(night), Date.valueOf(night));
112	    }
113	
114	    /** Reservas cuja entrada cai no intervalo [from, to). */
115	    public List<Reservation> startingBetween(LocalDate from, LocalDate to) {
116	        return query("WHERE check_in >= ? AND check_in < ? ORDER BY check_in, id", Date.valueOf(from), Date.valueOf(to));
117	    }
118	
119	    private List<Reservation> query(String clause, Date... params) {
120	        try (Connection c = ds.getConnection();
121	             PreparedStatement ps = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations " + clause)) {
122	            for (int i = 0; i < params.length; i++) ps.setDate(i + 1, params[i]);
123	            try (ResultSet rs = ps.executeQuery()) {
124	                List<Reservation> list = new ArrayList<>();
125	                while (rs.next()) list.add(map(rs));
126	                return list;
127	            }
128	        } catch (SQLException e) {
129	            throw new IllegalStateException(e);
130	        }
131	    }
132	
133	    private static void bind(PreparedStatement ps, Reservation r) throws SQLException {
134	        ps.setInt(1, r.roomNumber());
135	        ps.setString(2, r.guestName());
136	        ps.setString(3, r.guestEmail());
137	        ps.setString(4, r.guestCpf());
138	        ps.setDate(5, Date.valueOf(r.checkInDate()));
139	        ps.setDate(6, Date.valueOf(r.checkOutDate()));
140	        ps.setInt(7, r.guests());

