  1	package br.com.marealta;
  2	
  3	import br.com.marealta.messaging.MessageLog;
  4	import br.com.marealta.persistence.*;
  5	import br.com.marealta.service.ReservationService;
  6	import br.com.marealta.web.Routes;
  7	import com.fasterxml.jackson.databind.JsonNode;
  8	import com.fasterxml.jackson.databind.ObjectMapper;
  9	import io.javalin.Javalin;
 10	import org.junit.jupiter.api.*;
 11	
 12	import java.net.URI;
 13	import java.net.http.HttpClient;
 14	import java.net.http.HttpRequest;
 15	import java.net.http.HttpResponse;
 16	import java.util.Random;
 17	import javax.sql.DataSource;
 18	
 19	import static org.junit.jupiter.api.Assertions.*;
 20	import static org.junit.jupiter.api.Assumptions.assumeTrue;
 21	
 22	/** Usa o PostgreSQL de DB_URL/DB_USER/DB_PASSWORD; é pulado se não houver banco. Datas aleatórias evitam colisão entre execuções. */
 23	class ApiIntegrationTest {
 24	    static Javalin app;
 25	    static String base;
 26	    static int year;
 27	    static final HttpClient http = HttpClient.newHttpClient();
 28	    static final ObjectMapper om = new ObjectMapper();
 29	
 30	    @BeforeAll
 31	    static void start() {
 32	        String url = System.getenv("DB_URL");
 33	        assumeTrue(url != null, "sem DB_URL");
 34	        DataSource ds;
 35	        try {
 36	            ds = Database.connect(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 37	        } catch (RuntimeException e) {
 38	            assumeTrue(false, "banco indisponível");
 39	            return;
 40	        }
 41	        MessageLog log = new PostgresMessageLog(ds);
 42	        ReservationRepository repo = new ReservationRepository(ds);
 43	        app = new Routes(new ReservationService(repo, Main.messageSender(log, false, true)), repo, log).start(0);
 44	        base = "http://localhost:" + app.port();
 45	        year = 3000 + new Random().nextInt(5000);
 46	    }
 47	
 48	    @AfterAll
 49	    static void stop() { if (app != null) app.stop(); }
 50	
 51	    record Res(int status, String body) {
 52	        JsonNode json() throws Exception { return om.readTree(body); }
 53	    }
 54	
 55	    static Res call(String method, String path, String body) throws Exception {
 56	        var b = HttpRequest.newBuilder(URI.create(base + path));
 57	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 58	        var r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 59	        return new Res(r.statusCode(), r.body());
 60	    }
 61	
 62	    static String reservation(int room, String in, String out, int guests, String plan, String email) {
 63	        return """
 64	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"%s","guestCpf":"111.222.333-44",
 65	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, email, in, out, guests, plan);
 66	    }
 67	
 68	    @Test
 69	    void fullFlow() throws Exception {
 70	        String in = year + "-07-10", out = year + "-07-12";
 71	        Res created = call("POST", "/reservations", reservation(101, in, out, 2, "STANDARD", "carla@x.com"));
 72	        assertEquals(201, created.status());
 73	        JsonNode r = created.json();
 74	        long id = r.get("id").asLong();
 75	        assertEquals("PENDING", r.get("status").asText());
 76	        assertEquals(599.76, r.get("subtotal").asDouble());
 77	        assertTrue(r.get("refund").isNull());
 78	        assertEquals(409, call("POST", "/reservations", reservation(101, in, year + "-07-11", 1, "STANDARD", "a@b.com")).status());
 79	        assertEquals(409, call("GET", "/reservations/" + id + "/document", null).status());
 80	
 81	        Res confirmed = call("POST", "/reservations/" + id + "/confirmation", null);
 82	        assertEquals("CONFIRMED", confirmed.json().get("status").asText());
 83	        assertEquals(599.76, confirmed.json().get("amountPaid").asDouble());
 84	        assertEquals(409, call("POST", "/reservations/" + id + "/confirmation", null).status());
 85	
 86	        JsonNode msgs = call("GET", "/messages", null).json();
 87	        int n = msgs.size();
 88	        assertEquals("[Cópia] Reserva confirmada - Pousada Maré Alta", msgs.get(n - 1).get("subject").asText());
 89	        assertEquals("Reserva confirmada - Pousada Maré Alta", msgs.get(n - 2).get("subject").asText());
 90	        assertEquals("SENT", msgs.get(n - 2).get("status").asText());
 91	
 92	        Res occ = call("GET", "/reports/occupancy?date=" + in, null);
 93	        assertTrue(occ.body().contains("101,STANDARD," + id + "," + in + "," + out), occ.body());
 94	        assertTrue(occ.body().endsWith("total,1/5\n"), occ.body());
 95	        assertEquals("total,0/5\n", call("GET", "/reports/occupancy?date=" + out, null).body().lines().reduce((a, b) -> b).get() + "\n");
 96	
 97	        assertEquals(409, call("POST", "/reservations/" + id + "/check-out", null).status());
 98	        assertEquals("CHECKED_IN", call("POST", "/reservations/" + id + "/check-in", null).json().get("status").asText());
 99	        assertEquals(409, call("POST", "/reservations/" + id + "/cancellation", null).status());
100	        Res out1 = call("POST", "/reservations/" + id + "/check-out", null);
101	        assertEquals(200, out1.status());
102	        assertEquals("Comprovante de reserva", out1.json().get("title").asText());
103	        assertEquals(200, call("GET", "/reservations/" + id + "/document", null).status());
104	
105	        Res rev = call("GET", "/reports/revenue?month=" + year + "-07", null);
106	        assertTrue(rev.body().startsWith("reservation,room,check_in,check_out,status,amount\n"));
107	        assertTrue(rev.body().contains(id + ",101," + in + "," + out + ",CHECKED_OUT,599.76"), rev.body());
108	    }
109	
110	    @Test
111	    void cancellationAndErrors() throws Exception {
112	        String in = year + "-03-10", out = year + "-03-12";
113	        long id = call("POST", "/reservations", reservation(202, in, out, 3, "NON_REFUNDABLE", "ana@gmail")).json().get("id").asLong();
114	        call("POST", "/reservations/" + id + "/confirmation", null);
115	        JsonNode msgs = call("GET", "/messages", null).json();
116	        assertEquals("BLOCKED", msgs.get(msgs.size() - 1).get("status").asText());
117	        Res cancelled = call("POST", "/reservations/" + id + "/cancellation", null);
118	        assertEquals(0.0, cancelled.json().get("refund").asDouble());
119	        assertEquals(662.83, cancelled.json().get("amountPaid").asDouble());
120	        Res rev = call("GET", "/reports/revenue?month=" + year + "-03", null);
121	        assertTrue(rev.body().contains(id + ",202," + in + "," + out + ",CANCELLED,662.83"), rev.body());
122	        // quarto liberado após cancelamento
123	        assertEquals(201, call("POST", "/reservations", reservation(202, in, out, 1, "STANDARD", "a@b.com")).status());
124	
125	        assertEquals("INVALID_REQUEST", call("POST", "/reservations", "nope").json().get("error").asText());
126	        assertEquals(400, call("POST", "/reservations", reservation(101, out, in, 1, "STANDARD", "a@b.com")).status());
127	        assertEquals(400, call("POST", "/reservations", reservation(101, in, out, 0, "STANDARD", "a@b.com")).status());
128	        assertEquals(404, call("POST", "/reservations", reservation(999, in, out, 1, "STANDARD", "a@b.com")).status());
129	        assertEquals(422, call("POST", "/reservations", reservation(101, in, out, 3, "STANDARD", "a@b.com")).status());
130	        assertEquals(404, call("GET", "/reservations/999999999", null).status());
131	        assertEquals(400, call("GET", "/reports/occupancy?date=2027-13-01", null).status());
132	        assertEquals(400, call("GET", "/reports/revenue?month=2027-7", null).status());
133	        assertEquals(5, call("GET", "/rooms", null).json().size());
134	    }
135	}
