165	        assertEquals("ana@gmail.com", items.get(0).to());
166	        assertEquals("arquivo@pousadamarealta.com.br", items.get(1).to());
167	        assertEquals("[Cópia] Assunto", items.get(1).subject());
168	        assertEquals("Texto", items.get(1).body());
