178	        for (boolean test : new boolean[]{false, true}) {
179	            for (String bad : List.of("ana@gmail", "ana.gmail.com", "a@@b.com", "@b.com", "a@.com", "a@b.")) {
180	                var items = send(test, true, bad).items;
