194	        assertEquals("testes@pousadamarealta.com.br", m.to());
195	        assertEquals("[TESTE] Assunto", m.subject());
196	        assertEquals("Destinatário original: ana@gmail.com\nTexto", m.body());
197	        assertEquals(MessageStatus.SENT, m.status());
